function syncDescriptorAndClose(fd) {
  let failure;
  try {
    fsyncSync(fd);
  } catch (error) {
    failure = error;
  }
  try {
    closeSync(fd);
  } catch (error) {
    if (failure === undefined) failure = error;
  }
  if (failure !== undefined) throw failure;
}

function syncDirectoryChain(filePath) {
  let directory = path.dirname(path.resolve(filePath));
  for (;;) {
    const fd = openSync(directory, "r");
    syncDescriptorAndClose(fd);
    const parent = path.dirname(directory);
    if (parent === directory) return;
    directory = parent;
  }
}

function syncExistingFile(filePath) {
  const fd = openSync(filePath, "r");
  syncDescriptorAndClose(fd);
}

function writeFileAtomicNewDurable(filePath, content, options) {
  const temp = temporarySibling(filePath);
  ensureDirectory(path.dirname(filePath), { mode: options.directoryMode });
  let fd;
  try {
    fd = openSync(temp, "wx", options.mode === undefined ? 0o600 : options.mode);
    writeFileSync(fd, content);
    fsyncSync(fd);
    closeSync(fd);
    fd = undefined;
    try {
      linkSync(temp, filePath);
    } catch (error) {
      if (error.code === "EEXIST") {
        syncExistingFile(filePath);
        syncDirectoryChain(filePath);
      }
      throw error;
    }
    rmSync(temp, { force: true });
    syncDirectoryChain(filePath);
  } catch (error) {
    if (fd !== undefined) {
      try {
        closeSync(fd);
      } catch {
        // Preserve the primary operation failure.
      }
    }
    try {
      rmSync(temp, { force: true });
    } catch {
      // Preserve the primary operation failure.
    }
    throw error;
  }
}

/** Atomically create a new UTF-8 file or byte buffer without replacing an
 * existing target.
 *
 * This is the source-admission sibling of `writeFileAtomic`: projections are
 * replaceable, but source attempt artifacts are immutable facts. The temp file
 * is hard-linked into place, so an existing final path fails with `EEXIST`
 * instead of being overwritten; the temp sibling is then removed.
 *
 * Set `options.durable` to `true` to synchronize the staging file before it
 * is linked, then synchronize the file's directory chain from the containing
 * directory through the filesystem root. If the final path already exists,
 * its file and directory chain are synchronized before `EEXIST` is
 * propagated. A failure after linking may leave the final name published, so
 * callers must treat that outcome as uncertain. Durable mode assumes an
 * operator-controlled local filesystem whose storage binding honors hard-link
 * exclusion and file and directory synchronization; calling `fsync` does not
 * establish physical-media durability on every provider. This primitive does
 * not establish exactly-once execution, distributed exclusion, or whole-
 * journal durability.
 *
 * `options.mode` sets the file permissions, and `options.directoryMode` sets
 * those of any parent directory it creates. */
export function writeFileAtomicNew(filePath, content, options = {}) {
  if (Object.hasOwn(options, "durable") && typeof options.durable !== "boolean") {
    throw new TypeError("options.durable must be a Boolean");
  }
  if (options.durable === true) return writeFileAtomicNewDurable(filePath, content, options);

  const temp = temporarySibling(filePath);
  ensureDirectory(path.dirname(filePath), { mode: options.directoryMode });
  try {
    writeFileSync(temp, content, fileOptions(options));
    linkSync(temp, filePath);
    rmSync(temp, { force: true });
  } catch (error) {
    try {
      rmSync(temp, { force: true });
    } catch {
      // Preserve the original write/link failure.
    }
    throw error;
  }
}
